      <button type="button" data-kind="story" class="kind">Story <span class="n" data-n="story"></span></button>
      <button type="button" data-kind="missable" class="kind">Missable <span class="n" data-n="missable"></span></button>
      <button type="button" data-kind="collectibles" class="kind">Collectibles <span class="n" data-n="collectibles"></span></button>
      <button type="button" data-kind="activities" class="kind">Activities <span class="n" data-n="activities"></span></button>
