/* Leonida Trophy Guide: original dark neon look. System fonts only, no web fonts, no images. */
:root {
  --bg: #0d0a1a;
  --panel: #17122e;
  --panel-2: #1e1838;
  --line: #322a55;
  --text: #f2eefb;
  --muted: #b3a8d6;
  --pink: #ff2e88;
  --teal: #2de1c2;
  --gold: #f5b942;
  --silver: #c9d2e0;
  --bronze: #d08a4e;
  --platinum: #7fe3f0;
  --danger: #ff5d5d;
  --radius: 12px;
}
* { box-sizing: border-box; }
section, .trophy { scroll-margin-top: 170px; }
html { scroll-behavior: auto; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  line-height: 1.5;
}
.top {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: space-between;
  align-items: flex-start;
  padding: 22px 24px 16px;
  background: linear-gradient(135deg, #1b0f3a 0%, #2a0f3f 55%, #0f2a3a 100%);
  border-bottom: 3px solid var(--pink);
}
.brand { display: flex; gap: 14px; align-items: center; }
.mark {
  width: 56px; height: 56px; flex: none;
  display: grid; place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--pink), #8a2be2);
  color: #fff; font-weight: 800; font-size: 24px; letter-spacing: 1px;
  box-shadow: 0 0 22px rgba(255, 46, 136, .45);
}
h1 { margin: 0; font-size: 28px; line-height: 1.15; letter-spacing: .2px; }
.sub { margin: 4px 0 0; color: var(--muted); font-size: 14px; }
.progress-wrap { min-width: 280px; max-width: 420px; flex: 1; }
.progress-line { font-size: 15px; margin-bottom: 6px; }
.bar {
  height: 12px; border-radius: 999px; background: #241d45; overflow: hidden;
  border: 1px solid var(--line);
}
.bar-fill {
  height: 100%; border-radius: 999px;
  background: linear-gradient(90deg, var(--teal), var(--pink));
  transition: width .3s ease;
}
.grade-counts { margin-top: 6px; font-size: 13px; color: var(--muted); display: flex; flex-wrap: wrap; gap: 4px 14px; }
.controls {
  padding: 14px 24px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  display: flex; flex-direction: column; gap: 10px;
  position: sticky; top: 0; z-index: 10;
}
.control-row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.search { display: flex; gap: 8px; align-items: center; font-weight: 600; }
.search input {
  width: 260px; max-width: 70vw;
  background: var(--bg); color: var(--text);
  border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px;
  font-size: 14px;
}
.search input:focus, select:focus, button:focus { outline: 2px solid var(--teal); outline-offset: 1px; }
.check { display: flex; gap: 6px; align-items: center; cursor: pointer; font-size: 14px; }
.check input { width: 16px; height: 16px; accent-color: var(--pink); }
.kinds { display: flex; flex-wrap: wrap; gap: 8px; }
