.kind.active .n { color: #ffd7ea; }
select {
  background: var(--bg); color: var(--text);
  border: 1px solid var(--line); border-radius: 8px; padding: 7px 8px; font-size: 14px;
}
button {
  background: var(--teal); color: #06231d; border: none; border-radius: 8px;
  padding: 8px 14px; font-size: 14px; font-weight: 700; cursor: pointer;
}
