.stage h3 .step-no {
  display: inline-grid; place-items: center;
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--pink); color: #fff; font-size: 13px; margin-right: 6px;
}
.stage p { margin: 0; font-size: 14px; color: var(--muted); }
.stage .stage-count { margin-top: 8px; font-size: 13px; color: var(--teal); font-weight: 700; }
.trophy-list { display: flex; flex-direction: column; gap: 10px; }
