  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 12px 14px;
}
.trophy.earned { border-color: var(--teal); }
.trophy-head { display: flex; gap: 10px; align-items: flex-start; }
.trophy-head input { width: 20px; height: 20px; margin-top: 3px; accent-color: var(--teal); flex: none; }
